@ParameterizedTest
@NullAndEmptySource
@Tag("fast")
void placeOrder_nullOrEmptyLines_throwsIllegalArgumentException(List<OrderLine> invalidLines) {
    assertThatThrownBy(() -> orderService.placeOrder("CUST-1", invalidLines))
            .isInstanceOf(IllegalArgumentException.class);
}

@ParameterizedTest
@CsvSource({"0, 10.0", "-1, 10.0", "5, -1.0"})
void placeOrder_invalidQuantityOrPrice_throwsIllegalArgumentException(int qty, double price) {
    var invalidLine = new OrderLine("SKU-1", qty, price);
    assertThatThrownBy(() -> orderService.placeOrder("CUST-1", List.of(invalidLine)))
            .isInstanceOf(IllegalArgumentException.class);
}

